package store

import (
  "context"

  "github.com/jackc/pgx/v5/pgxpool"
)

type Order struct {
  ID     int64
  UserID int64
  Total  int64
}

type Store struct {
  pool *pgxpool.Pool
}

func (s *Store) OrdersByUser(ctx context.Context, userID int64) ([]Order, error) {
  rows, err := s.pool.Query(ctx, "SELECT id, user_id, total FROM orders WHERE user_id = $1", userID)
  if err != nil {
    return nil, err
  }
  var orders []Order
  for rows.Next() {
    var o Order
    if err := rows.Scan(&o.ID, &o.UserID, &o.Total); err != nil {
      return nil, err
    }
    orders = append(orders, o)
  }
  return orders, nil
}

func (s *Store) HasLargeOrder(ctx context.Context, userID, limit int64) (bool, error) {
  rows, err := s.pool.Query(ctx, "SELECT total FROM orders WHERE user_id = $1", userID)
  if err != nil {
    return false, err
  }
  for rows.Next() {
    var total int64
    if err := rows.Scan(&total); err != nil {
      return false, err
    }
    if total > limit {
      return true, nil
    }
  }
  return false, nil
}

