  for rows.Next() {
    var o Order
    if err := rows.Scan(&o.ID, &o.UserID, &o.Total); err != nil {
      return nil, err
    }
    orders = append(orders, o)
  }
  if err := rows.Err(); err != nil {
    return nil, err
  }
  return orders, nil
}

func (s *Store) HasLargeOrder(ctx context.Context, userID, limit int64) (bool, error) {
  rows, err := s.pool.Query(ctx, "SELECT total FROM orders WHERE user_id = $1", userID)
  if err != nil {
    return false, err
  }
  defer rows.Close()

  for rows.Next() {
    var total int64
    if err := rows.Scan(&total); err != nil {
      return false, err
    }
    if total > limit {
      return true, nil
    }
  }
  return false, rows.Err()
}

func (s *Store) OrdersByUser(ctx context.Context, userID int64) ([]Order, error) {
  rows, err := s.pool.Query(ctx, "SELECT * FROM orders WHERE user_id = $1", userID)
  if err != nil {
    return nil, err
  }
  return pgx.CollectRows(rows, pgx.RowToStructByName[Order])
}

func (s *Store) HasLargeOrder(ctx context.Context, userID, limit int64) (bool, error) {
  var found bool
  err := s.pool.QueryRow(ctx,
    "SELECT EXISTS (SELECT 1 FROM orders WHERE user_id = $1 AND total > $2)",
    userID, limit,
  ).Scan(&found)
  return found, err
}
